def capital_words_spaces(s: str) -> str:
    def insert_spaces(word: str) -> str:
        # Insert a space before each capital letter that is not at the start
        return re.sub(r'(?<!^)(?=[A-Z])', ' ', word)

    # Split the string by spaces to preserve existing spaces
    words = s.split(' ')
    # Process each word independently to add spaces before capitals inside it
    processed_words = [insert_spaces(word) for word in words]
    # Rejoin with single spaces
    return ' '.join(processed_words)

